        if not self._text.startswith("[", self._pos):
            return self._parse_number()
        self._pos += 1
        values = [self._parse_number()]
        while self._text.startswith(",", self._pos):
            self._pos += 1
            values.append(self._parse_number())
        self._expect("]")
        return values

